    21→func (s *Service) decodePubsubMessage(msg *pubsub.Message) (ssz.Unmarshaler, error) {
    22→	if msg == nil || msg.Topic == nil || *msg.Topic == "" {
    23→		return nil, errNilPubsubMessage
    24→	}
    25→	topic := *msg.Topic
    26→	fDigest, err := p2p.ExtractGossipDigest(topic)
    27→	if err != nil {
    28→		return nil, errors.Wrapf(err, "extraction failed for topic: %s", topic)
    29→	}
    30→	topic = strings.TrimSuffix(topic, s.cfg.p2p.Encoding().ProtocolSuffix())
    31→	topic, err = s.replaceForkDigest(topic)
    32→	if err != nil {
    33→		return nil, err
    34→	}
    35→	// Specially handle subnet messages.
    36→	switch {
    37→	case strings.Contains(topic, p2p.GossipAttestationMessage):
    38→		topic = p2p.GossipTypeMapping[reflect.TypeOf(&ethpb.Attestation{})]
    39→		// Given that both sync message related subnets have the same message name, we have to
    40→		// differentiate them below.
    41→	case strings.Contains(topic, p2p.GossipSyncCommitteeMessage) && !strings.Contains(topic, p2p.SyncContributionAndProofSubnetTopicFormat):
    42→		topic = p2p.GossipTypeMapping[reflect.TypeOf(&ethpb.SyncCommitteeMessage{})]
    43→	case strings.Contains(topic, p2p.GossipBlobSidecarMessage):
    44→		topic = p2p.GossipTypeMapping[reflect.TypeOf(&ethpb.BlobSidecar{})]
    45→	case strings.Contains(topic, p2p.GossipDataColumnSidecarMessage):
    46→		topic = p2p.GossipTypeMapping[reflect.TypeOf(&ethpb.DataColumnSidecar{})]
    47→	}
    48→
    49→	base := p2p.GossipTopicMappings(topic, 0)
    50→	if base == nil {
    51→		return nil, p2p.ErrMessageNotMapped
    52→	}
    53→	m, ok := base.(ssz.Unmarshaler)
    54→	if !ok {
    55→		return nil, errors.Errorf("message of %T does not support marshaller interface", base)
    56→	}
    57→	// Handle different message types across forks.
    58→	dt, err := extractValidDataTypeFromTopic(topic, fDigest[:], s.cfg.clock)
    59→	if err != nil {
    60→		return nil, err
    61→	}
    62→	if dt != nil {
    63→		m = dt
    64→	}
    65→	if err := s.cfg.p2p.Encoding().DecodeGossip(msg.Data, m); err != nil {
    66→		return nil, err
    67→	}
    68→	return m, nil
    69→}
