    71→// Replaces our fork digest with the formatter.
    72→func (*Service) replaceForkDigest(topic string) (string, error) {
    73→	subStrings := strings.Split(topic, "/")
    74→	if len(subStrings) != 4 {
    75→		return "", p2p.ErrInvalidTopic
    76→	}
    77→	subStrings[2] = "%x"
    78→	return strings.Join(subStrings, "/"), nil
