    81→func extractValidDataTypeFromTopic(topic string, digest []byte, clock *startup.Clock) (ssz.Unmarshaler, error) {
    82→	switch topic {
    83→	case p2p.BlockSubnetTopicFormat:
    84→		return extractDataTypeFromTypeMap(types.BlockMap, digest, clock)
    85→	case p2p.AttestationSubnetTopicFormat:
    86→		return extractDataTypeFromTypeMap(types.AttestationMap, digest, clock)
    87→	case p2p.AggregateAndProofSubnetTopicFormat:
    88→		return extractDataTypeFromTypeMap(types.AggregateAttestationMap, digest, clock)
    89→	case p2p.AttesterSlashingSubnetTopicFormat:
    90→		return extractDataTypeFromTypeMap(types.AttesterSlashingMap, digest, clock)
    91→	case p2p.LightClientOptimisticUpdateTopicFormat:
    92→		return extractDataTypeFromTypeMap(types.LightClientOptimisticUpdateMap, digest, clock)
    93→	case p2p.LightClientFinalityUpdateTopicFormat:
    94→		return extractDataTypeFromTypeMap(types.LightClientFinalityUpdateMap, digest, clock)
    95→	}
    96→	return nil, nil
    97→}
